const state={data:null,session:null,project:null,version:1,left:'artboards',right:'assistant',selected:null,selectedRefs:new Set(),proposal:null,preview:null,previewVersion:null,zoom:.6,tool:'select',region:null,prompt:'',paintPrompt:'Refine the tonal modelling and tissue surfaces while preserving the supplied anatomical drawing.',model:'local',conversation:[],runId:null,agentError:'',busy:false,search:'',jobs:[],media:new Map()};
