function toast(message,error=false){const e=$('#toast');e.textContent=message;e.classList.toggle('error',error);e.hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>e.hidden=true,error?9500:3600)}
function modal(title,html,wide=false){$('#modal-title').textContent=title;$('#modal-content').innerHTML=html;$('#modal').style.width=wide?'1120px':'720px';$('#modal').showModal()}
function busy(value){state.busy=value;$$('[data-submit]').forEach(b=>b.disabled=value||b.dataset.unavailable==='true')}
async function guarded(fn){try{return await fn()}catch(e){toast(e.message||String(e),true);console.error(e)}}
function getFrame(project=state.preview||state.project){return project.frames.find(f=>f.id===project.active_frame)||project.frames[0]}
function template(tid){const t=clone(state.data.templates.find(t=>t.id===tid));if(!t)throw Error('Unknown template');delete t.svg;t.template_id=tid;t.id=uid('frame');return Object.assign(t,{stage:'colour',show_labels:true,detail:1,hidden_layers:[],geometry_locked:true,artwork_media_id:null})}
function newProject(title,tid){const f=template(tid);return {schema_version:'2.1.0',id:uid('project'),title,frames:[f],active_frame:f.id,references:[],brief:'',style:{name:'Clinical atlas',locked:true}}}
function readDB(){try{const text=localStorage.getItem(STORAGE);return text?JSON.parse(text):(memoryDB||{projects:{},history:{},proposals:{},media:{}})}catch(e){return memoryDB||{projects:{},history:{},proposals:{},media:{}}}}
function saveDB(db){const data=JSON.stringify(db);localStorage.setItem(STORAGE,data);memoryDB=db}
function checkProject(p){if(p.schema_version!=='2.1.0'||!Array.isArray(p.frames)||!p.frames.length||p.frames.length>40)throw Error('Invalid project format');if(!p.title||p.title.length>160)throw Error('Project title must be 1–160 characters');for(const r of p.references||[])if(r.url&&!/^https?:\/\//.test(r.url))throw Error('Use HTTP or HTTPS source URLs');for(const f of p.frames){if(f.kind==='plate'){const d=f.document,a=state.assets[d.asset];if(!a)throw Error('Unknown anatomical asset');if(d.anatomy.view!==a.view)throw Error('A text field cannot change anatomical viewpoint');if(!Number.isFinite(d.label_size)||d.label_size<10||d.label_size>32||d.label_size*d.print_width_mm*72/25.4/d.width<7)throw Error('Label size must remain at least 7 pt at print width');const [x,y,w,h]=d.art_box;if(![x,y,w,h].every(Number.isFinite)||w<=0||h<=0||x<0||y<115||x+w>d.width||y+h>d.height-150)throw Error('Artwork must remain inside the illustration area');if(!['colour','values','contours'].includes(f.stage))throw Error('Unknown stage');if(!Number.isFinite(f.detail)||f.detail<0||f.detail>1.5)throw Error('Texture intensity must be 0–1.5');for(const l of d.labels){if(!a.landmarks[l.landmark]||!['left','right'].includes(l.side)||!l.text||l.text.length>120)throw Error('Invalid anatomical label');if(l.target&&(!l.target_note||l.target.some(v=>!Number.isFinite(v)||v<0||v>1)))throw Error('Target correction requires normalized coordinates and a reason')}}else if(f.kind==='graphics'){if(!['photo','vector'].includes(f.document.engine))throw Error('Invalid editing engine');}else if(!state.data.templates.some(t=>t.id===f.template_id||t.id===f.document.id))throw Error('Use a bundled schematic template in the standalone workspace')}}
function apply(p,ops){p=clone(p);if(!ops.length||ops.length>24)throw Error('Use 1–24 editing operations');for(const o of ops){if(o.op==='add_frame'){const f=template(o.template_id);if(o.new_id)f.id=o.new_id;p.frames.push(f);p.active_frame=f.id;continue}if(o.op==='select_frame'){if(!p.frames.some(f=>f.id===o.frame_id))throw Error('Unknown artboard');p.active_frame=o.frame_id;continue}if(o.op==='remove_frame'){if(p.frames.length<2)throw Error('Keep one artboard');p.frames=p.frames.filter(f=>f.id!==o.frame_id);p.active_frame=p.frames[0].id;continue}if(o.op==='graphics_result'){const current=getFrame(p);if(current.kind==='graphics'&&current.document.engine===o.document.engine&&!o.append)current.document=clone(o.document);else{const f={id:o.new_id,kind:'graphics',document:clone(o.document),stage:'colour',show_labels:false,detail:1,hidden_layers:[],geometry_locked:true,artwork_media_id:null};p.frames.push(f);p.active_frame=f.id;}continue}if(o.op==='project_title'){p.title=o.value;continue}if(o.op==='brief'){p.brief=o.value;continue}const f=p.frames.find(f=>f.id===(o.frame_id||p.active_frame));if(!f)throw Error('Unknown artboard');const d=f.document;switch(o.op){case 'title':case 'subtitle':case 'caption':case 'description':d[o.op]=o.value;break;case 'stage':f.stage=o.value;break;case 'show_labels':f.show_labels=o.value;break;case 'detail':f.detail=o.value;break;case 'geometry_lock':f.geometry_locked=o.value;break;case 'label_size':if(f.kind!=='plate')throw Error('Use an atlas plate');d.label_size=o.value;break;case 'art_box':d.art_box=o.value;break;case 'label':{const l=d.labels.find(l=>l.landmark===o.landmark);if(!l)throw Error('Unknown label');const allowed=['text','side','y','target','target_note'];if(Object.keys(o.values).some(k=>!allowed.includes(k)))throw Error('Unknown label property');Object.assign(l,o.values);break}case 'layer':if(!o.layer_id.startsWith('texture-')&&f.geometry_locked)throw Error('Geometry is locked');f.hidden_layers=f.hidden_layers.filter(x=>x!==o.layer_id);if(!o.visible)f.hidden_layers.push(o.layer_id);break;case 'move_node':{const n=d.nodes.find(n=>n.id===o.node_id);if(!n)throw Error('Unknown node');n.box=o.box;break}case 'add_node':if(f.kind!=='scene')throw Error('Use a schematic artboard for symbols');if(!state.assets[o.asset])throw Error('Unknown asset');d.nodes.push({id:o.new_id||uid('node'),asset:o.asset,box:o.box});break;default:throw Error('Unsupported edit: '+o.op)}}checkProject(p);return p}
function localPlan(prompt,p){const ops=[];for(const text of prompt.split(';').map(s=>s.trim()).filter(Boolean)){const q=text.toLowerCase();let m;if(['show contours','contours','line drawing'].includes(q))ops.push({op:'stage',value:'contours'});else if(['show values','values','grayscale','greyscale'].includes(q))ops.push({op:'stage',value:'values'});else if(['show colour','show color','colour','color','restore colour'].includes(q))ops.push({op:'stage',value:'colour'});else if(['hide labels','artwork only'].includes(q))ops.push({op:'show_labels',value:false});else if(['show labels','restore labels'].includes(q))ops.push({op:'show_labels',value:true});else if(['less texture','reduce texture','simplify texture'].includes(q))ops.push({op:'detail',value:.45});else if(['restore texture','full texture'].includes(q))ops.push({op:'detail',value:1});else if(m=q.match(/^(?:set )?labels? (?:size )?(\d+(?:\.\d+)?)$/))ops.push({op:'label_size',value:+m[1]});else if(m=text.match(/^(?:set )?(title|subtitle|caption)\s*:\s*(.+)$/i))ops.push({op:m[1].toLowerCase(),value:m[2]});else if(m=q.match(/^add (atlas-[a-z-]+)$/))ops.push({op:'add_frame',template_id:m[1]});else if(m=text.match(/^rename ([a-z0-9-]+)\s*:\s*(.+)$/))ops.push({op:'label',landmark:m[1],values:{text:m[2]}});else if(m=q.match(/^move ([a-z0-9-]+) (left|right) (\d+(?:\.\d+)?)$/))ops.push({op:'label',landmark:m[1],values:{side:m[2],y:+m[3]}});else throw Error('Local commands: show contours; show colour; hide labels; labels 18; less texture; title: ...; rename cortex: ...; move cortex left 330. Free-form interpretation requires the server and a configured model.')}for(const o of ops)if(['add_frame','add_node'].includes(o.op))o.new_id=uid(o.op==='add_frame'?'frame':'node');apply(p,ops);return {summary:prompt,operations:ops,provider:'Local commands (no model)',warnings:[]}}
async function offlineRequest(path,options={}){const method=options.method||'GET',b=options.body?JSON.parse(options.body):{},db=readDB();const parts=path.split('?')[0].split('/').filter(Boolean),params=new URLSearchParams(path.split('?')[1]||'');const pid=parts[2];if(path==='/api/session')return {token:'offline',mode:'standalone',version:'2.1.0',providers:{local:true,ollama:false,figurelabs:false}};if(path==='/api/bootstrap')return JSON.parse(embedded.textContent);if(parts[1]==='projects'&&parts.length===2){if(method==='POST'){const p=newProject(b.title||'Untitled illustration',b.template_id||'atlas-kidney-section');db.projects[p.id]={project:p,version:1};db.history[p.id]=[{project:clone(p),version:1,reason:'Created project',created:new Date().toISOString()}];saveDB(db);return db.projects[p.id]}return Object.values(db.projects).map(v=>({id:v.project.id,title:v.project.title,version:v.version}))}if(path==='/api/import'){const p=clone(b.project);checkProject(p);if(p.frames.some(f=>f.artwork_media_id)||p.references.some(r=>r.media_id))throw Error('This JSON needs its media; restore from the server bundle');p.id=uid('project');db.projects[p.id]={project:p,version:1};db.history[p.id]=[{project:clone(p),version:1,reason:'Imported project',created:new Date().toISOString()}];saveDB(db);return db.projects[p.id]}const snap=db.projects[pid];if(!snap)throw Error('Project not found');function commit(p,reason){if(b.base_version!==undefined&&b.base_version!==snap.version)throw Error('Project changed; reload before applying this edit');snap.project=p;snap.version++;db.history[pid].push({project:clone(p),version:snap.version,reason,created:new Date().toISOString()});saveDB(db);return clone(snap)}if(parts.length===3){if(params.has('version')){const h=db.history[pid].find(h=>h.version===+params.get('version'));if(!h)throw Error('Unknown revision');return {project:clone(h.project),version:h.version}}return clone(snap)}switch(parts[3]){case 'edit':return commit(apply(snap.project,b.operations),b.reason||'Manual edit');case 'history':return db.history[pid].map(({version,reason,created})=>({version,reason,created})).reverse();case 'restore':{const old=db.history[pid].find(h=>h.version===b.version);if(!old)throw Error('Unknown revision');return commit(clone(old.project),'Restored revision '+b.version)}case 'agent':{if(b.provider!=='local')throw Error('Model inference requires the local server');if(b.base_version!==snap.version)throw Error('Stale proposal');const plan=localPlan(b.prompt,snap.project);const q={...plan,id:uid('proposal'),project_id:pid,base_version:snap.version,status:'pending'};db.proposals[q.id]=q;saveDB(db);return q}case 'proposals':{if(parts.length===4)return Object.values(db.proposals).filter(q=>q.project_id===pid);const q=db.proposals[parts[4]];if(!q)throw Error('Proposal not found');if(parts[5]==='decide'){if(q.status!=='pending')throw Error('Proposal is no longer pending');if(b.accept){if(q.base_version!==snap.version)throw Error('Proposal is stale; manual edits have been preserved');q.status='accepted';return commit(apply(snap.project,q.operations),q.summary)}q.status='rejected';saveDB(db);return {rejected:true}}return q}case 'references':{if(method==='POST'){let mid=null;if(b.data){if(!/\.(png|jpe?g|webp|txt|md|csv)$/i.test(b.name))throw Error('Use the server for PDF or SVG reference parsing');mid=uid('media');const mime=/\.png$/i.test(b.name)?'image/png':/\.jpe?g$/i.test(b.name)?'image/jpeg':/\.webp$/i.test(b.name)?'image/webp':'text/plain';db.media[mid]={name:b.name,mime,data:b.data};}const p=clone(snap.project);p.references.push({id:uid('ref'),title:b.title,url:b.url||'',note:b.note||'',licence:b.licence||'Not specified',media_id:mid});return commit(p,'Added reference')}const r=snap.project.references.find(r=>r.id===parts[4]);return {text:r?.note||''}}case 'paint':if(method==='GET')return [];throw Error('Reference-guided painting requires the local server and FIGURELABS_API_KEY');default:throw Error('This action requires the local server')}}
async function request(path,options={},retry=true){if(offline)return offlineRequest(path,options);const r=await fetch(path,{...options,headers:{'Content-Type':'application/json','X-Studio-Token':state.session?.token||'',...(options.headers||{})}});if(r.status===403&&retry){const problem=await r.clone().json().catch(()=>({}));if(String(problem.error||'').includes('session token')){state.session=await request('/api/session',{},false);return request(path,options,false)}}if(!r.ok){let m;try{const j=await r.json();m=j.error||j.detail}catch(e){m=r.statusText}throw Error(typeof m==='string'?m:JSON.stringify(m))}return r.json()}
const post=(path,b)=>request(path,{method:'POST',body:JSON.stringify(b)});
async function edit(ops,reason='Manual edit'){if(state.editorSession?.dirty)throw Error('Save editor changes before changing the artboard');if(offline&&getFrame(state.project).kind==='scene'&&ops.some(o=>!['add_frame','select_frame','remove_frame','project_title','brief'].includes(o.op)))throw Error('Standalone schematic artboards are read-only. Use the local server to update symbols and their connected edges.');if(state.preview)throw Error('Return to the current revision before editing');const r=await post('/api/projects/'+state.project.id+'/edit',{base_version:state.version,operations:ops,reason});state.project=r.project;state.version=r.version;state.editorSession=null;renderAll();switchWorkspace('canvas');return r}
async function loadProject(pid){if(state.editorSession?.dirty)throw Error('Save editor changes before switching projects');state.editorSession=null;const r=await request('/api/projects/'+pid);state.project=r.project;state.version=r.version;state.preview=null;state.proposal=null;state.selected=null;state.region=null;state.media.clear();state.selectedRefs.clear();await loadMedia();state.conversation=offline?[]:await request('/api/projects/'+pid+'/conversation');renderAll();switchWorkspace('canvas');await loadProposals()}
async function loadMedia(){for(const r of state.project.references){if(r.media_id)await mediaURL(r.media_id)}for(const f of state.project.frames){if(f.artwork_media_id)await mediaURL(f.artwork_media_id);if(f.kind==='graphics')await mediaURL(f.document.preview_media_id)}}
async function mediaURL(mid){if(state.media.has(mid))return state.media.get(mid);let uri;if(offline){const m=readDB().media[mid];if(!m)return '';uri='data:'+m.mime+';base64,'+m.data}else{const r=await fetch('/api/projects/'+state.project.id+'/media/'+mid);if(!r.ok)return '';const blob=await r.blob();uri=await new Promise(res=>{const rd=new FileReader();rd.onload=()=>res(rd.result);rd.readAsDataURL(blob)})}state.media.set(mid,uri);return uri}
function svgDoc(svg){const d=new DOMParser().parseFromString(svg,'image/svg+xml');if(d.querySelector('parsererror'))throw Error('Invalid illustration SVG');return d.documentElement}
function normalizeSVG(a,frame,prefix){const root=svgDoc(a.svg);for(const n of [...root.querySelectorAll('[id]')])if(frame.hidden_layers?.includes(n.id))n.remove();for(const n of root.querySelectorAll('[id]')){if(n.id.startsWith('texture-')){if(frame.stage==='contours'){n.remove();continue}n.setAttribute('opacity',+(n.getAttribute('opacity')||1)*frame.detail)}}for(const n of [root,...root.querySelectorAll('*')]){for(const attr of [...n.attributes]){if(attr.name==='id')n.setAttribute('id',prefix+attr.value);else if(attr.value.includes('url(#'))n.setAttribute(attr.name,attr.value.replace(/url\(#([\w.-]+)\)/g,(_,id)=>'url(#'+prefix+id+')'));}if(frame.stage==='values')for(const attr of [...n.attributes])n.setAttribute(attr.name,attr.value.replace(/#[0-9a-fA-F]{6}\b/g,c=>{const g=Math.round(.2126*parseInt(c.slice(1,3),16)+.7152*parseInt(c.slice(3,5),16)+.0722*parseInt(c.slice(5,7),16)).toString(16).padStart(2,'0');return '#'+g+g+g}));if(frame.stage==='contours'&&['path','ellipse','circle','polygon','polyline','rect'].includes(n.localName)){n.setAttribute('fill','none');n.setAttribute('stroke','#74695f');n.setAttribute('stroke-width','.9');n.setAttribute('opacity','.65')}}root.querySelectorAll(':scope > title,:scope > desc').forEach(n=>n.remove());return [...root.children].map(n=>new XMLSerializer().serializeToString(n)).join('')}
function assetEmbed(a,box,frame,id='anatomy'){const [x,y,w,h]=box,[vx,vy,aw,ah]=a.view_box;const sc=Math.min(w/aw,h/ah);return `<g id="node-${escape(id)}" transform="translate(${x+w/2} ${y+h/2}) scale(${sc}) translate(${-vx-aw/2} ${-vy-ah/2})">${normalizeSVG(a,frame,'asset-'+id+'-')}</g>`}
const metrics=document.createElement('canvas').getContext('2d');
function textWidth(s,size){metrics.font=size+'px Arial';return metrics.measureText(s).width}
function wrap(s,width,size){const out=[];for(const paragraph of String(s).split('\n')){let line='';for(const word of paragraph.split(/\s+/)){if(line&&textWidth(line+' '+word,size)>width){out.push(line);line=word}else line+=(line?' ':'')+word}out.push(line)}return out}
function svgText(s,x,y,width,size,fill='#38332e',family='Arial, sans-serif'){const lines=wrap(s,width,size);return `<text x="${x}" y="${y+size*.96}" fill="${fill}" font-family="${family}" font-size="${size}">${lines.map((t,i)=>`<tspan x="${x}" dy="${i?size*1.28:0}">${escape(t)}</tspan>`).join('')}</text>`}
function labelRows(d,a){const out=[],fs=d.label_size,[x,y,w,h]=d.art_box,[vx,vy,aw,ah]=a.view_box,sc=Math.min(w/aw,h/ah);for(const side of ['left','right']){const rows=d.labels.filter(l=>l.side===side).map(l=>{const pt=l.target||a.landmarks[l.landmark];const target=[x+w/2+(pt[0]-.5)*aw*sc,y+h/2+(pt[1]-.5)*ah*sc];const lines=wrap(l.text,d.label_bank_width,fs);return {label:l,target,lines,height:lines.length*fs*1.28,desired:l.y??target[1],side,x:side==='left'?42:d.width-42-d.label_bank_width,width:d.label_bank_width}}).sort((a,b)=>a.desired-b.desired);const start=145,end=d.height-170,gap=18;if(rows.reduce((n,r)=>n+r.height+gap,0)>end-start)throw Error('Label bank is overfull; split the plate');rows.forEach((r,i)=>r.y=Math.max(r.desired-r.height/2,i?rows[i-1].y+rows[i-1].height+gap:start));if(rows.length&&rows.at(-1).y+rows.at(-1).height>end){rows.at(-1).y=end-rows.at(-1).height;for(let i=rows.length-2;i>=0;i--)rows[i].y=Math.min(rows[i].y,rows[i+1].y-rows[i].height-gap)}out.push(...rows)}return out}
function renderSVG(frame){const d=frame.document;if(frame.kind==='graphics')return `<svg xmlns="${NS}" viewBox="0 0 ${d.width} ${d.height}" width="190mm" height="${190*d.height/d.width}mm"><title>${escape(d.title)}</title><image width="${d.width}" height="${d.height}" href="${state.media.get(d.preview_media_id)||''}"/></svg>`;if(frame.kind==='scene')return renderScene(frame);const a=state.assets[d.asset],w=d.width,h=d.height,fs=d.label_size;let art=assetEmbed(a,d.art_box,frame);if(frame.artwork_media_id){const src=state.media.get(frame.artwork_media_id);if(src){const [x,y,bw,bh]=d.art_box;art=`<g id="node-anatomy"><image x="${x}" y="${y}" width="${bw}" height="${bh}" preserveAspectRatio="xMidYMid meet" href="${src}"/></g>`}}let svg=`<svg xmlns="${NS}" viewBox="0 0 ${w} ${h}" width="${d.print_width_mm}mm" height="${d.print_width_mm*h/w}mm" role="img" aria-labelledby="plate-title plate-desc"><title id="plate-title">${escape(d.title)}</title><desc id="plate-desc">${escape(d.description)}</desc><rect width="${w}" height="${h}" fill="#fff"/>${svgText(d.title,42,23,w-84,30,'#292620','Georgia, serif')}${svgText(d.subtitle,42,67,w-84,15,'#69645e')}${art}`;if(frame.show_labels){svg+='<g id="plate-labels">';for(const r of labelRows(d,a)){const [tx,ty]=r.target,cy=r.y+r.height/2;let sx,ex;if(r.side==='left'){const tw=Math.max(...r.lines.map(l=>textWidth(l,fs)));sx=r.x+tw+7;ex=Math.max(sx+8,Math.min(tx-15,r.x+r.width+22))}else{sx=r.x-8;ex=Math.min(sx-8,Math.max(tx+15,r.x-25))}svg+=`<g id="plate-label-${escape(r.label.landmark)}"><path d="M${sx} ${cy} L${ex} ${cy} L${tx} ${ty}" stroke="#665e57" stroke-width=".85" fill="none"/><circle cx="${tx}" cy="${ty}" r="1.6" fill="#665e57"/>${svgText(r.label.text,r.x,r.y-fs*.12,r.width,fs)}</g>`}svg+='</g>'}svg+=svgText(d.caption,42,h-115,w-84,14,'#625b53')+svgText(d.reference_line,42,h-47,w-84,11,'#7a7269')+'</svg>';return svg}
function renderScene(f){if(offline){const t=state.data.templates.find(t=>t.id===f.template_id||t.id===f.document.id);return t?.svg||'';}const t=state.data.templates.find(t=>t.id===f.template_id||t.id===f.document.id);if(!t?.svg)return `<svg xmlns="${NS}" viewBox="0 0 1200 800"><rect width="1200" height="800" fill="white"/></svg>`;const root=svgDoc(t.svg),d=f.document;const title=root.querySelector('#figure-title');if(title)title.textContent=d.title;const desc=root.querySelector('#figure-description');if(desc)desc.textContent=d.description;const texts=[...root.children].filter(n=>n.localName==='text');if(texts[0]){texts[0].textContent=d.title}if(texts.length>1&&t.document.subtitle)texts[1].textContent=d.subtitle;for(const n of d.nodes){const a=state.assets[n.asset];if(!a||!n.box)continue;const old=root.querySelector('[id="node-'+n.id+'"]');const box=n.box,sc=Math.min(box[2]/a.view_box[2],box[3]/a.view_box[3]),rot=n.rotation||0;const g=svgDoc(`<svg xmlns="${NS}">${assetEmbed(a,box,{...f,stage:'colour'},n.id)}</svg>`).firstElementChild;if(old)old.replaceWith(g);else root.append(g);if(rot)g.setAttribute('transform',g.getAttribute('transform').replace(' scale(',` rotate(${rot}) scale(`))}return new XMLSerializer().serializeToString(root)}
