function describeOp(o){if(o.op==='graphics_result')return o.document.engine==='vector'?'Editable vector artwork':'Layered pixel artwork';const names={title:'Title',subtitle:'Subtitle',caption:'Caption',description:'Description',label_size:'Label size',detail:'Texture',stage:'Drawing stage',show_labels:'Label visibility',art_box:'Artwork position',move_node:'Symbol position',add_node:'Add symbol',project_title:'Project name',brief:'Brief'};if(o.op==='label'){const name=getFrame(state.project).document.labels?.find(l=>l.landmark===o.landmark)?.text||o.landmark.replace(/-/g,' ');const v=o.values||{};return name+': '+(v.text||[v.side,v.y!==undefined?'position '+Math.round(v.y):null].filter(Boolean).join(', '))}if(o.op==='add_frame')return 'Add artboard: '+(state.data.templates.find(t=>t.id===o.template_id)?.name||o.template_id.replace(/-/g,' '));if(o.op==='show_labels')return o.value?'Show labels':'Hide labels';if(o.op==='add_node')return 'Add symbol: '+(state.assets[o.asset]?.label||o.asset);if(o.op==='art_box'||o.op==='move_node')return names[o.op];return (names[o.op]||o.op.replace(/_/g,' '))+(o.value!==undefined?': '+String(o.value):'')}
