async function runAgent(){if(state.busy)return;if(state.editorSession?.dirty)throw Error('Save editor changes to the project before requesting an agent edit');switchWorkspace('canvas');if(state.preview){state.preview=null;state.previewVersion=null;renderCanvas()}const prompt=$('#agent-prompt').value.trim();if(!prompt)throw Error('Enter an instruction');const consent=$('#model-consent')?.checked||false;if(state.model!=='local'&&!consent)throw Error('Authorize this model request before sending');state.agentError='';state.runId=crypto.randomUUID();state.conversation.push({prompt,answer:''});busy(true);$('#stop-agent').hidden=state.model!=='codex';$('#stop-agent').disabled=false;$('#stop-agent').textContent='Stop';$('#agent-prompt').readOnly=true;$('#model-provider').disabled=true;renderConversation();try{state.proposal=await post(`/api/projects/${state.project.id}/${state.model==='codex'?'composer':'agent'}`,{base_version:state.version,prompt,provider:state.model,run_id:state.runId,reference_ids:[...state.selectedRefs],consent});const turn=state.conversation[state.conversation.length-1];turn.answer=state.proposal.summary;turn.trace=state.proposal.trace||[];if(!state.proposal.no_edit){state.preview=apply(state.project,state.proposal.operations);for(const op of state.proposal.operations)if(op.op==='graphics_result')await mediaURL(op.document.preview_media_id);fit();}else state.proposal=null;state.prompt='';$('#agent-prompt').value='';renderCanvas();renderProposal()}catch(e){state.agentError=e.message||String(e);state.conversation[state.conversation.length-1].answer='The request did not complete. No edit was applied.';throw e}finally{state.runId=null;busy(false);$('#agent-prompt').readOnly=false;$('#model-provider').disabled=false;$('#stop-agent').hidden=true;renderConversation()}}

