function renderPaint(root){if(!state.session.providers.figurelabs){root.innerHTML=`<div class="panel-body"><h2>Paint & adjust</h2><button id="pixel-editor-open" class="primary full" ${offline?'disabled':''}>Image tools</button><div class="presets" style="margin-top:20px"><button data-pixel-prompt="Improve the contrast gently while preserving colours and all anatomy.">Improve contrast</button><button data-pixel-prompt="Make a separate grayscale teaching version with the photo editor.">Make a grayscale version</button><button data-pixel-prompt="Inspect the layers and explain what I can edit.">Explore image layers</button></div></div>`;$('#pixel-editor-open').onclick=()=>guarded(()=>fullEditor('photo'));$$('[data-pixel-prompt]').forEach(b=>b.onclick=()=>{state.model='codex';state.prompt=b.dataset.pixelPrompt;state.right='assistant';renderRight();$('#agent-prompt').focus()});return}const f=getFrame(state.project);root.innerHTML=`<div class="panel-body"><h2>Paint</h2><div class="notice">${state.session.providers.figurelabs?'FigureLabs':'Painting provider is not connected.'}</div><label class="field"><span>Painting instruction</span><textarea id="paint-instruction" class="prompt-box">${escape(state.paintPrompt)}</textarea></label><div id="region-description" class="small">${state.region?'Selected region: '+state.region.map(n=>Math.round(n*100)+'%').join(', '):'Whole artwork · choose Region to edit a smaller area.'}</div><button id="clear-region" class="link-button" ${state.region?'':'hidden'}>Clear selected region</button><label class="check-row"><input id="paint-consent" type="checkbox">Send the artwork and instruction to FigureLabs. I authorize this potentially chargeable request.</label><button class="primary full" id="paint-submit" data-submit data-unavailable="${!state.session.providers.figurelabs||f.kind!=='plate'}" ${!state.session.providers.figurelabs||f.kind!=='plate'?'disabled':''}>Generate a candidate</button><p class="instruction" style="margin-top:13px">Labels stay separate. Review the result before accepting it.</p><div class="divider"></div><h3>Anatomy to preserve</h3><p class="small">${escape((state.data.contracts[f.document.asset]?.invariants||['Keep the existing diagram structure.']).join(' '))}</p><div id="paint-jobs"></div></div>`;$('#paint-instruction').oninput=e=>state.paintPrompt=e.target.value;$('#clear-region').onclick=()=>{state.region=null;showRegion();renderRight()};$('#paint-submit').onclick=()=>guarded(async()=>{if(state.busy)return;busy(true);try{await post(`/api/projects/${state.project.id}/paint`,{base_version:state.version,instruction:state.paintPrompt,consent:$('#paint-consent').checked,region:state.region});toast('Candidate request submitted. Refresh its status below.');await loadJobs()}finally{busy(false)}});guarded(loadJobs)}
async function loadJobs(){state.jobs=await request(`/api/projects/${state.project.id}/paint`);const root=$('#paint-jobs');if(!root)return;for(const j of state.jobs)if(j.candidate_media_id)await mediaURL(j.candidate_media_id);root.innerHTML=state.jobs.map(j=>`<div class="paint-job"><strong>${escape(j.status.replace(/_/g,' '))}</strong><span>${escape(j.instruction)}</span>${j.error?`<div class="notice">${escape(typeof j.error==='string'?j.error:JSON.stringify(j.error))}</div>`:''}${j.candidate_media_id?`<img src="${state.media.get(j.candidate_media_id)}" alt="Unreviewed painted candidate"><button class="secondary full" data-candidate="${j.candidate_media_id}">Review candidate</button>`:j.task_id?`<button class="secondary full" data-refresh="${j.id}">Refresh status</button>`:''}</div>`).join('');$$('[data-refresh]').forEach(b=>b.onclick=()=>guarded(async()=>{b.disabled=true;await post(`/api/projects/${state.project.id}/paint/${b.dataset.refresh}/refresh`,{});await loadJobs()}));$$('[data-candidate]').forEach(b=>b.onclick=()=>candidateDialog(b.dataset.candidate))}
function candidateDialog(mid){modal('Review painted candidate',`<img src="${state.media.get(mid)}" alt="Painted candidate" style="width:100%;max-height:480px;object-fit:contain"><p>Check the anatomical structures and label targets before accepting the artwork.</p><label class="check-row"><input type="checkbox" id="confirm-landmarks">I have checked all leader targets against this replacement artwork.</label><button id="adopt-candidate" class="primary full">Use this candidate</button>`);$('#adopt-candidate').onclick=()=>guarded(async()=>{const r=await post(`/api/projects/${state.project.id}/adopt`,{base_version:state.version,frame_id:state.project.active_frame,media_id:mid,confirm_landmarks:$('#confirm-landmarks').checked});state.project=r.project;state.version=r.version;$('#modal').close();renderAll()})}
function artRect(f){const d=f.document,a=state.assets[d.asset],[x,y,w,h]=d.art_box,[vx,vy,aw,ah]=a.view_box,sc=Math.min(w/aw,h/ah);return [x+(w-aw*sc)/2,y+(h-ah*sc)/2,aw*sc,ah*sc]}
