function bindCanvas(){const svg=$('#paper>svg');if(!svg)return;let drag=null;function point(e){const r=svg.getBoundingClientRect(),[w,h]=dims(getFrame());return [(e.clientX-r.left)*w/r.width,(e.clientY-r.top)*h/r.height]}svg.onpointerdown=e=>{if(e.button!==0||state.preview)return;const p=point(e),f=getFrame(state.project);if(state.tool==='region'){if(f.kind!=='plate'){toast('Region painting applies to atlas artwork.',true);return}drag={kind:'region',start:p};svg.setPointerCapture(e.pointerId);e.preventDefault();return}const label=e.target.closest('[id^="plate-label-"]');if(label){state.selected=label.id.replace('plate-label-','');state.right='inspector';renderRight();drag={kind:'label',id:state.selected,start:p,el:label,moved:false};svg.setPointerCapture(e.pointerId);e.preventDefault();return}const node=e.target.closest('[id^="node-"]');if(node&&f.kind==='scene'&&!offline){const id=node.id.slice(5),n=f.document.nodes.find(n=>n.id===id);if(n?.box){drag={kind:'node',id,start:p,box:clone(n.box),el:node,transform:node.getAttribute('transform')};svg.setPointerCapture(e.pointerId);e.preventDefault()}}};svg.onpointermove=e=>{if(!drag)return;const p=point(e),dx=p[0]-drag.start[0],dy=p[1]-drag.start[1];if(drag.kind==='region'){const [x,y,w,h]=artRect(getFrame(state.project));const l=Math.max(x,Math.min(drag.start[0],p[0])),t=Math.max(y,Math.min(drag.start[1],p[1])),r=Math.min(x+w,Math.max(drag.start[0],p[0])),b=Math.min(y+h,Math.max(drag.start[1],p[1]));if(r>l&&b>t){state.region=[(l-x)/w,(t-y)/h,(r-l)/w,(b-t)/h];showRegion()}}else if(drag.kind==='label'){if(Math.abs(dx)+Math.abs(dy)>2){drag.moved=true;drag.el.setAttribute('transform',`translate(${dx} ${dy})`)}}else drag.el.setAttribute('transform',`translate(${dx} ${dy}) ${drag.transform}`)};svg.onpointerup=e=>{if(!drag)return;const q=drag,p=point(e);drag=null;if(q.kind==='region'){state.right='paint';renderRight();return}if(q.kind==='label'){if(q.moved)guarded(()=>edit([{op:'label',landmark:q.id,values:{side:p[0]<getFrame().document.width/2?'left':'right',y:p[1]}}],'Moved label'));else renderCanvas()}else guarded(()=>edit([{op:'move_node',node_id:q.id,box:[q.box[0]+p[0]-q.start[0],q.box[1]+p[1]-q.start[1],q.box[2],q.box[3]]}],'Moved schematic symbol'))};svg.onpointercancel=()=>{drag=null;renderCanvas()}}
