function referenceDialog(){modal('Add source material',`<p>Files stay local unless you include them in a model request.</p><label class="field"><span>Source title</span><input id="ref-title" type="text" placeholder="Atlas, paper, reference drawing or commission"></label><label class="field"><span>URL</span><input id="ref-url" type="url" placeholder="https://..."></label><label class="field"><span>Relevant excerpt or instruction</span><textarea id="ref-note"></textarea></label><label class="field"><span>Licence or permission</span><input id="ref-licence" type="text" placeholder="Record the actual reuse terms"></label><label class="field"><span>Optional local file</span><input type="file" id="ref-file" accept=".png,.jpg,.jpeg,.webp,.svg,.pdf,.txt,.md,.csv,.json"></label><p class="small">${offline?'Raster images and text files. Use the local server for PDF and SVG.':'Scanned PDFs need OCR. Keep patient-identifying material out of model requests.'}</p><button id="save-reference" class="primary full" data-submit>Add reference</button>`);$('#save-reference').onclick=()=>guarded(async()=>{const title=$('#ref-title').value.trim();if(!title)throw Error('Enter a source title');const file=$('#ref-file').files[0];let data=null;if(file){if(file.size>16000000)throw Error('Reference limit is 16 MB');data=await new Promise((res,rej)=>{const r=new FileReader();r.onload=()=>res(String(r.result).split(',')[1]);r.onerror=rej;r.readAsDataURL(file)})}const r=await post(`/api/projects/${state.project.id}/references`,{base_version:state.version,title,url:$('#ref-url').value,note:$('#ref-note').value,licence:$('#ref-licence').value||'Not specified',name:file?.name||null,data});state.project=r.project;state.version=r.version;await loadMedia();state.left='references';$('#modal').close();renderAll()})}
