async function exportFile(fmt){if(fmt==='native'){if(state.preview)throw Error('Accept or discard the preview first');const r=await fetch(`/api/projects/${state.project.id}/graphics/native`);if(!r.ok)throw Error('Cannot export native artwork');download(await r.blob(),filename()+(getFrame(state.project).document.engine==='vector'?'.vectorcraft':'.pcraft'));return}if(state.preview)throw Error('Return to the current revision or accept the proposal before exporting');if(!offline){const r=await fetch(`/api/projects/${state.project.id}/export/${fmt}?frame_id=${state.project.active_frame}`);if(!r.ok){const j=await r.json();throw Error(j.error||j.detail||'Export failed')}download(await r.blob(),filename()+'.'+(fmt==='control'?'control.json':fmt));return}if(fmt==='json'){download(JSON.stringify(state.project,null,2),filename()+'.json','application/json');return}const svg=renderSVG(getFrame(state.project));if(fmt==='svg'){download(svg,filename()+'.svg','image/svg+xml');return}if(fmt==='png'){const url=URL.createObjectURL(new Blob([svg],{type:'image/svg+xml'})),image=new Image();await new Promise((resolve,reject)=>{image.onload=resolve;image.onerror=()=>reject(Error('Cannot rasterize illustration'));image.src=url});const [w,h]=dims(getFrame()),c=document.createElement('canvas');c.width=2400;c.height=Math.round(2400*h/w);c.getContext('2d').drawImage(image,0,0,c.width,c.height);URL.revokeObjectURL(url);const blob=await new Promise(res=>c.toBlob(res,'image/png'));download(blob,filename()+'.png');return}throw Error('Use the local server for PDF, PowerPoint, media bundles and control-record exports')}
