const tree=d.inspection;function show(value,depth=0){if(depth>5||!value)return '';if(Array.isArray(value))return value.slice(0,80).map(v=>show(v,depth)).join('');if(typeof value!=='object')return '';const name=value.name||value.title||value.kind||value.type;return (name?`<div class="graphics-layer" style="padding-left:${depth*10}px">${escape(name)}</div>`:'')+Object.entries(value).filter(([k,v])=>['layers','children','nodes','document','documents'].includes(k)&&typeof v==='object').map(([k,v])=>show(v,depth+(name?1:0))).join('')}
$('#graphics-layers').innerHTML=show(tree)||'<p>Ask the assistant to inspect or change an object.</p>';$('#native-editor').onclick=()=>guarded(()=>fullEditor(d.engine));$('#native-export').onclick=()=>guarded(()=>exportFile('native'));$('#graphics-commands').onclick=graphicsDialog;
