async function importGraphics(file,engine,options={}){if(state.preview)throw Error('Accept or discard the preview first');if(file.size>16000000)throw Error('Artwork limit is 16 MB');const data=await new Promise((res,rej)=>{const r=new FileReader();r.onload=()=>res(String(r.result).split(',')[1]);r.onerror=rej;r.readAsDataURL(file)});const r=await post(`/api/projects/${state.project.id}/graphics/import`,{base_version:state.version,engine,name:file.name,data,...options});state.project=r.project;state.version=r.version;state.proposal=null;state.preview=null;state.previewVersion=null;await loadMedia();renderAll();fit()}
